-- PLAN NRW: 12 Tipp-Seiten „Ausbildung meistern“ (29.10.2026, Texte freigegeben von P. Schenkelberger)
-- Im Supabase-SQL-Editor ausführen. Legt nur an, wenn der Slug noch nicht existiert. Seiten: plan-nrw.de/wissen/<slug>

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-erster-tag-neuer-einsatz', 'Erster Tag im neuen Einsatz – Tipps für Pflege-Azubis', $j${"definition": "Neue Station, neue Gesichter, niemand hat Zeit für dich – und du weißt nicht mal, wo die Handschuhe liegen.", "was_hilft": ["Stell dich jedem kurz vor: Name, Ausbildungsjahr, wie lange du bleibst.", "Frag gleich am ersten Tag: „Wer ist meine Praxisanleitung und wann können wir das Erstgespräch machen?“", "Nimm einen kleinen Block mit: Abläufe, Telefonnummern, Fragen – alles ohne Patientennamen.", "Lies deine Lernziele für den Einsatz vorher und bring sie mit."], "merksatz": "Du musst am ersten Tag nichts können – nur fragen, zuhören und dich zeigen."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-erster-tag-neuer-einsatz');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-praxisanleitung-keine-zeit', 'Praxisanleitung hat keine Zeit – was tun?', $j${"definition": "Seit Wochen keine geplante Anleitung. Du läufst einfach mit und hast das Gefühl, nichts zu lernen.", "was_hilft": ["Schlag selbst einen Termin vor: „Können wir am Donnerstag 30 Minuten für meinen Praxisauftrag einplanen?“", "Mach es konkret: ein Thema, eine Tätigkeit, ein Patient – statt „irgendwann mal“.", "Schreib dir auf, wann Anleitung stattfand und wann nicht (das ist für dich gedacht und nicht zum Anklagen).", "Ändert sich nichts: Sprich deine Leitende Praxisanleitung oder deine Lehrkraft in der Pflegeschule an. Sie begleiten dich auch in der Praxis.", "Bedenke aber auch, dass Praxisanleiter im Stationsdienst voll eingebunden sind und sich meistens um mehrere Auszubildende kümmern müssen."], "merksatz": "Wer einen konkreten Termin vorschlägt, bekommt häufiger einen.", "gut_zu_wissen": "Mindestens 10 % der Zeit in jedem Einsatz muss geplante und strukturierte Praxisanleitung sein (§ 4 PflAPrV)."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-praxisanleitung-keine-zeit');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-praxisauftrag-ansprechen', 'Praxisauftrag richtig ansprechen', $j${"definition": "Die Schule hat dir einen Praxisauftrag mitgegeben. Auf Station weiß niemand, was das ist.", "was_hilft": ["Zeig den Auftrag in der ersten Woche, nicht am letzten Tag.", "Erkläre in einem Satz, was du üben sollst und was du dafür brauchst.", "Frag, welcher Patient oder welche Situation dafür passt.", "Plane eine kurze Nachbesprechung ein – dort lernst du am meisten."], "merksatz": "Ein Praxisauftrag ist kein Zusatzaufwand für die Station – er ist deine Anleitung auf Papier."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-praxisauftrag-ansprechen');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-lernen-schichtdienst', 'Lernen trotz Schichtdienst – Tipps fürs Pflegeexamen', $j${"definition": "Früh, Spät, Nacht – und dazwischen sollst du fürs Examen lernen. Feste Lernzeiten klappen nie.", "was_hilft": ["Plane nach Schicht, nicht nach Wochentag: Frühdienst = nachmittags 30 Minuten, Spätdienst = vormittags, nach dem Nachtdienst = nichts.", "Kleine Einheiten statt Marathon: 15 Minuten Quiz in der Bahn zählen.", "Freie Tage für die großen Themen, Arbeitstage für Wiederholung.", "Schlaf geht vor: Müde gelernt bleibt kaum hängen."], "merksatz": "Jeden Tag ein bisschen schlägt einmal die Woche alles."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-lernen-schichtdienst');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-blackout-muendliche-pruefung', 'Blackout in der mündlichen Prüfung – was hilft?', $j${"definition": "Die Frage ist einfach – und plötzlich ist alles weg.", "was_hilft": ["Atme ein- bis dreimal tief ein und langsam aus, bevor du antwortest. Eine kurze Pause ist erlaubt.", "Sag es offen: „Einen Moment, ich sortiere meine Gedanken.“", "Fang beim Bekannten an: Was sehe ich beim Patienten? Was wäre mein erster Schritt?", "Frag nach, wenn du die Frage nicht verstehst. Das ist kein Minuspunkt."], "merksatz": "Prüfer wollen sehen, wie du denkst – nicht, wie schnell du sprichst."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-blackout-muendliche-pruefung');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-nacht-vor-dem-examen', 'Die Nacht vor dem Pflegeexamen', $j${"definition": "Morgen ist es so weit. Du liegst wach und gehst zum zehnten Mal deine Karteikarten durch.", "was_hilft": ["Am Vorabend nichts Neues mehr lernen – nur noch kurz überfliegen, was du schon kannst.", "Tasche, Ausweis, Unterlagen und Weg schon abends fertig machen.", "Etwas Normales tun: essen, spazieren, eine Serie.", "Kannst du nicht schlafen: Liegen und ruhen ist auch Erholung."], "merksatz": "Was du bis heute gelernt hast, nimmt dir keine schlaflose Nacht mehr weg."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-nacht-vor-dem-examen');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-kritik-annehmen', 'Kritik in der Pflegeausbildung annehmen', $j${"definition": "Vor dem Patienten oder im Dienstzimmer: „Das war falsch.“ Du fühlst dich klein und willst dich nur rechtfertigen.", "was_hilft": ["Erst zuhören, nicht sofort erklären. Dann: „Was genau soll ich beim nächsten Mal anders machen?“", "Trenne Sache und Ton: Die Kritik kann berechtigt sein, auch wenn der Ton es nicht ist.", "War es vor Patienten oder unfair: Sprich es später unter vier Augen an – ruhig und mit einem Beispiel.", "Schreib dir den Punkt auf. Beim nächsten Mal zeigen, dass du ihn umgesetzt hast."], "merksatz": "Kritik an deinem Handeln ist keine Kritik an dir als Mensch."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-kritik-annehmen');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-kollegin-macht-runter', 'Wenn eine Kollegin dich immer wieder runtermacht', $j${"definition": "Eine Person im Team korrigiert dich vor anderen, macht Sprüche oder ignoriert dich. Es passiert nicht einmal, sondern ständig.", "was_hilft": ["Beschreibe das Verhalten, nicht den Menschen: „Wenn du mich vor dem Patienten korrigierst, verunsichert mich das. Kannst du es mir danach sagen?“", "Notiere Datum, was passiert ist und wer dabei war – ohne Patientendaten.", "Hol dir Unterstützung: Praxisanleitung, Stationsleitung, Lehrkraft oder die Jugend- und Auszubildendenvertretung (JAV).", "Bleib nicht allein damit. Wiederholte Herabsetzung ist kein „so ist das halt in der Pflege“."], "merksatz": "Du darfst Grenzen setzen – auch als Azubi."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-kollegin-macht-runter');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-fordernde-angehoerige', 'Umgang mit fordernden Angehörigen', $j${"definition": "Ein Angehöriger steht laut im Flur und will sofort wissen, warum seine Mutter noch nicht gewaschen ist.", "was_hilft": ["Ruhig bleiben und Sorge anerkennen: „Ich verstehe, dass Sie sich Sorgen machen.“", "Nur sagen, was du sicher weißt – Diagnosen und Befunde erklärt die Ärztin oder der Arzt.", "Hol die zuständige Pflegefachperson dazu, wenn es über deine Aufgabe hinausgeht.", "Wird es bedrohlich: Abstand halten, Hilfe holen, nicht allein bleiben."], "merksatz": "Hinter Lautstärke steckt meistens Angst um einen Menschen."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-fordernde-angehoerige');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-erster-todesfall', 'Der erste Todesfall in der Pflegeausbildung', $j${"definition": "Ein Patient, den du gepflegt hast, ist gestorben. Vielleicht warst du dabei. Du funktionierst weiter – und zu Hause kommt alles hoch.", "was_hilft": ["Alle Gefühle sind normal: Traurigkeit, Leere, auch gar nichts zu fühlen.", "Sprich mit jemandem aus dem Team darüber, der das kennt. Frag ruhig: „Wie gehst du damit um?“", "Ein kleines Abschiedsritual kann helfen: kurz im Zimmer bleiben, ein Gedanke, ein Fenster öffnen.", "Lass dir Zeit. Wenn es dich nach Wochen noch stark belastet, hol dir Unterstützung."], "merksatz": "Dass es dich berührt, zeigt, dass du gut pflegst.", "hilfe": true}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-erster-todesfall');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-gewalt-durch-patienten', 'Gewalt durch Patienten – was Azubis tun können', $j${"definition": "Ein Patient schlägt, kratzt, beleidigt dich oder fasst dich an, wo er nicht soll. Hinterher heißt es vielleicht: „Der ist halt verwirrt.“", "was_hilft": ["Deine Sicherheit geht vor: Abstand, Hilfe holen, nicht allein ins Zimmer.", "Es ist nicht deine Schuld – auch nicht, wenn der Patient krank oder verwirrt ist.", "Melde jeden Vorfall bei der Leitung. Bei Verletzungen: Durchgangsarzt bzw. Unfallversicherung – es kann ein Arbeitsunfall sein.", "Sprich danach mit jemandem darüber, auch wenn „zum Glück nichts passiert ist“."], "merksatz": "„Gehört zum Job“ gilt nicht für Gewalt. Melden schützt dich und die anderen.", "hilfe": true}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-gewalt-durch-patienten');

insert into public.lerninhalte (typ, kategorie, slug, titel, daten, aktiv, quelle, stand, geprueft_von, geprueft_am)
select 'grundlagen', 'Ausbildung meistern', 'ausbildung-pausen-ueberstunden', 'Pausen und Überstunden in der Pflegeausbildung', $j${"definition": "Die Pause fällt schon wieder aus, und „kannst du noch eine Stunde bleiben?“ hörst du fast jeden Tag.", "was_hilft": ["Pausen: Erwachsene mehr als 6 Stunden Arbeit = mindestens 30 Minuten, mehr als 9 Stunden = 45 Minuten (§ 4 ArbZG). Unter 18: mehr als 4,5 Stunden = 30 Minuten, mehr als 6 Stunden = 60 Minuten (§ 11 JArbSchG).", "Überstunden: Nur ausnahmsweise erlaubt und müssen extra bezahlt oder in Freizeit ausgeglichen werden (§ 19 PflBG).", "Ansprechpartner im Betrieb: Praxisanleitung, Stationsleitung, Jugend- und Auszubildendenvertretung (JAV) oder Betriebs-/Personalrat.", "Klärt sich nichts: Pflegeschule und die Ombudsstelle für die Pflegeausbildung NRW bei der Bezirksregierung Münster – sie vermittelt bei Konflikten mit dem Ausbildungsbetrieb."], "merksatz": "Deine Ausbildung hat Regeln – und die gelten auch, wenn die Station voll ist."}$j$::jsonb, true, 'PLAN – Tipps aus der Praxis; ArbZG, JArbSchG, PflBG, PflAPrV', '2026-10-29', 'P. Schenkelberger', '2026-10-29'
where not exists (select 1 from public.lerninhalte where slug = 'ausbildung-pausen-ueberstunden');

